/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readThemesFromSaveRoot, readCollectedThemeNamesFromSaveRoot
 * depends    src/save/access/values, src/save/catalogs/themes, src/save/catalogs/types, src/save/themes/types
 * used by    src/calculators/specs.generated, src/save/themes/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { listThemeCatalogRows } from '../catalogs/themes'
import { type ThemeCatalogCategory } from '../catalogs/types'
import { coerceSaveNumber } from '../access/values'
import type { ThemeItemSaveRow, ThemesSaveExtract } from './types'

const THEME_UNLOCK_SAVE_KEYS: Record<ThemeCatalogCategory, readonly string[]> = {
  tower: ['towerUnlocked', 'diceTowers'],
  background: ['backgroundUnlocked', 'diceBackgrounds'],
  menu: ['menuUnlocked'],
  profileBanner: ['profileBannerUnlocked'],
  guardian: ['guardianSkinUnlocked'],
  song: ['trackAvailable'],
}

function readSaveBoolean(value: unknown): boolean {
  return value === true
}

function readBoolUnlockArray(value: unknown): boolean[] {
  if (!Array.isArray(value)) return []
  return value.map(readSaveBoolean)
}

function isThemeUnlockedInSave(
  root: Record<string, unknown>,
  category: ThemeCatalogCategory,
  catalogIndex: number,
): boolean {
  for (const key of THEME_UNLOCK_SAVE_KEYS[category]) {
    const flags = readBoolUnlockArray(root[key])
    if (flags[catalogIndex] === true) return true
  }
  return false
}

/** The save key holding the selected item's index, per category. */
const THEME_SELECTED_SAVE_KEYS: Partial<Record<ThemeCatalogCategory, string>> = {
  tower: 'selectedTower',
  background: 'selectedBackground',
  menu: 'selectedMenu',
  profileBanner: 'selectedProfileBanner',
  guardian: 'guardianSkinIndex',
}

/**
 * Every unlocked theme item by category and index, and what is selected.
 *
 * `readCollectedThemeNamesFromSaveRoot` answers a narrower question, the set of names, and so
 * folds "Glitch" the tower and "Glitch" the background into one and drops an index the catalog
 * has no row for. This keeps both: the catalog names every slot game data v29.2.1 defines, and an
 * index past those comes back with a null name and a warning.
 */
export function readThemesFromSaveRoot(root: Record<string, unknown> | null): ThemesSaveExtract | null {
  if (!root) return null
  const warnings: string[] = []
  const names = new Map(listThemeCatalogRows().map(row => [`${row.category}:${row.catalogIndex}`, String(row.label || row.name || '').trim() || null]))
  const selected: Partial<Record<ThemeCatalogCategory, number>> = {}
  for (const [category, key] of Object.entries(THEME_SELECTED_SAVE_KEYS) as [ThemeCatalogCategory, string][]) {
    const index = coerceSaveNumber(root[key])
    if (index !== null) selected[category] = index
  }

  const unlocked: ThemeItemSaveRow[] = []
  let anyList = false
  for (const [category, keys] of Object.entries(THEME_UNLOCK_SAVE_KEYS) as [ThemeCatalogCategory, readonly string[]][]) {
    const indices = new Set<number>()
    for (const key of keys) {
      if (Array.isArray(root[key])) anyList = true
      readBoolUnlockArray(root[key]).forEach((flag, index) => { if (flag) indices.add(index) })
    }
    const unnamed: number[] = []
    for (const index of [...indices].sort((a, b) => a - b)) {
      const name = names.get(`${category}:${index}`) ?? null
      if (name === null) unnamed.push(index)
      unlocked.push({ category, index, name, selected: selected[category] === index })
    }
    if (unnamed.length) warnings.push(`Unlocked ${category} items ${unnamed.join(', ')} have no catalog row.`)
  }
  if (!anyList) return null

  return { unlocked, selected, skinsBought: coerceSaveNumber(root.totalSkinsBought), warnings }
}

/** Theme names as used by the `collectedThemes` map (catalog label). */
export function readCollectedThemeNamesFromSaveRoot(
  root: Record<string, unknown> | null,
): string[] {
  if (!root) return []

  const names = new Set<string>()
  for (const row of listThemeCatalogRows()) {
    if (!isThemeUnlockedInSave(root, row.category, row.catalogIndex)) continue
    const name = String(row.label || row.name || '').trim()
    if (name) names.add(name)
  }

  return [...names].sort((a, b) => a.localeCompare(b))
}
